DO $$ DECLARE sc client_contracts; uid uuid; BEGIN
 SELECT id INTO uid FROM units WHERE code='CLI3924';
 IF EXISTS (SELECT 1 FROM client_contracts WHERE contract_code='CON16177') THEN
  UPDATE client_contracts SET unit_id=uid,start_date='2026-08-01',original_start_date=coalesce(original_start_date,'2026-08-01'),end_date='2026-12-31',expiry_date='2026-12-31',payroll_window_id='9676d05d-fbb3-4d9a-bdca-b4b9ac65db0c',status='active',approval_status='approved',approved_at=coalesce(approved_at,now()),description='ITC CPO Ranjangaon - SG/Supervisor 26 days',updated_at=now() WHERE contract_code='CON16177';
 ELSE
  SELECT * INTO sc FROM client_contracts WHERE contract_code='CON14293';
  INSERT INTO client_contracts SELECT * FROM jsonb_populate_record(null::client_contracts, to_jsonb(sc) || jsonb_build_object('id',gen_random_uuid(),'contract_code','CON16177','unit_id',uid,'description','ITC CPO Ranjangaon - SG/Supervisor 26 days','start_date','2026-08-01','original_start_date','2026-08-01','end_date','2026-12-31','expiry_date','2026-12-31','payroll_window_id','9676d05d-fbb3-4d9a-bdca-b4b9ac65db0c','status','active','approval_status','approved','approved_at',now(),'signed_pdf_url','','signed_at',null,'renewal_count',0,'created_at',now(),'updated_at',now()));
