DO $$ DECLARE sc client_contracts; uid uuid; BEGIN
 SELECT id INTO uid FROM units WHERE code='CLI4374';
 IF EXISTS (SELECT 1 FROM client_contracts WHERE contract_code='CON16048') THEN
  UPDATE client_contracts SET unit_id=uid,start_date='2026-06-19',original_start_date=coalesce(original_start_date,'2026-06-19'),end_date='2027-03-31',expiry_date='2027-03-31',payroll_window_id='59c7f3a7-342c-42d5-9783-9bf3b173d266',status='active',approval_status='approved',approved_at=coalesce(approved_at,now()),description='Bajel Projects Saswad Road - SG/Supervisor 26 days',updated_at=now() WHERE contract_code='CON16048';
 ELSE
  SELECT * INTO sc FROM client_contracts WHERE contract_code='CON14293';
  INSERT INTO client_contracts SELECT * FROM jsonb_populate_record(null::client_contracts, to_jsonb(sc) || jsonb_build_object('id',gen_random_uuid(),'contract_code','CON16048','unit_id',uid,'description','Bajel Projects Saswad Road - SG/Supervisor 26 days','start_date','2026-06-19','original_start_date','2026-06-19','end_date','2027-03-31','expiry_date','2027-03-31','payroll_window_id','59c7f3a7-342c-42d5-9783-9bf3b173d266','status','active','approval_status','approved','approved_at',now(),'signed_pdf_url','','signed_at',null,'renewal_count',0,'created_at',now(),'updated_at',now()));
 END IF; END $$;
